#include "MobileRemote.h"
#import <UIKit/UIKit.h>
#import <AVFoundation/AVFoundation.h>
@interface ZLRemoteScanner:UIViewController<AVCaptureMetadataOutputObjectsDelegate>{@public std::function<void(juce::String)> completion;AVCaptureSession* capture;AVCaptureVideoPreviewLayer* preview;BOOL finished;}
@end
@implementation ZLRemoteScanner
-(UIInterfaceOrientationMask)supportedInterfaceOrientations{return UIInterfaceOrientationMaskLandscape;}
-(void)viewDidLoad{[super viewDidLoad];self.view.backgroundColor=[UIColor blackColor];UIButton* cancel=[UIButton buttonWithType:UIButtonTypeSystem];cancel.frame=CGRectMake(55,25,100,44);[cancel setTitle:@"Cancel" forState:UIControlStateNormal];NSString* lang=[NSLocale preferredLanguages].firstObject;if([lang hasPrefix:@"pt"])[cancel setTitle:@"Cancelar" forState:UIControlStateNormal];else if([lang hasPrefix:@"es"])[cancel setTitle:@"Cancelar" forState:UIControlStateNormal];[cancel addTarget:self action:@selector(cancelScan) forControlEvents:UIControlEventTouchUpInside];[self.view addSubview:cancel];AVCaptureDevice* camera=[AVCaptureDevice defaultDeviceWithMediaType:AVMediaTypeVideo];NSError* error=nil;AVCaptureDeviceInput* input=camera?[AVCaptureDeviceInput deviceInputWithDevice:camera error:&error]:nil;if(!input){[self finish:@""];return;}capture=[[AVCaptureSession alloc] init];if(![capture canAddInput:input]){[self finish:@""];return;}[capture addInput:input];AVCaptureMetadataOutput* output=[[[AVCaptureMetadataOutput alloc] init] autorelease];if(![capture canAddOutput:output]){[self finish:@""];return;}[capture addOutput:output];[output setMetadataObjectsDelegate:self queue:dispatch_get_main_queue()];output.metadataObjectTypes=@[AVMetadataObjectTypeQRCode];preview=[[AVCaptureVideoPreviewLayer layerWithSession:capture] retain];preview.videoGravity=AVLayerVideoGravityResizeAspectFill;[self.view.layer insertSublayer:preview atIndex:0];dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{[capture startRunning];});}
-(void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];preview.frame=self.view.bounds;if(preview.connection.isVideoOrientationSupported)preview.connection.videoOrientation=self.view.window.windowScene.interfaceOrientation==UIInterfaceOrientationLandscapeRight?AVCaptureVideoOrientationLandscapeRight:AVCaptureVideoOrientationLandscapeLeft;}
-(void)captureOutput:(AVCaptureOutput*)output didOutputMetadataObjects:(NSArray<__kindof AVMetadataObject*>*)objects fromConnection:(AVCaptureConnection*)connection{for(AVMetadataMachineReadableCodeObject* code in objects)if([code.stringValue hasPrefix:@"zlplay-remote:"]){[self finish:code.stringValue];break;}}
-(void)cancelScan{[self finish:@""];}
-(void)finish:(NSString*)value{if(finished)return;finished=YES;auto callback=completion;juce::String result=juce::String::fromUTF8(value.UTF8String);if(capture)dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{[capture stopRunning];});[self dismissViewControllerAnimated:YES completion:^{if(callback)callback(result);}];}
-(void)dealloc{[preview release];[capture release];[super dealloc];}
@end
namespace mobile {
void scanRemoteQR(std::function<void(String)> completion){if(![AVCaptureDevice defaultDeviceWithMediaType:AVMediaTypeVideo]){completion({});return;}auto begin=[completion]{UIWindow* window=nil;for(UIScene* scene in [UIApplication sharedApplication].connectedScenes)if([scene isKindOfClass:[UIWindowScene class]])for(UIWindow* candidate in ((UIWindowScene*)scene).windows)if(candidate.isKeyWindow)window=candidate;UIViewController* owner=window.rootViewController;while(owner.presentedViewController)owner=owner.presentedViewController;if(!owner||![AVCaptureDevice defaultDeviceWithMediaType:AVMediaTypeVideo]){completion({});return;}auto* scanner=[[ZLRemoteScanner alloc] init];scanner->completion=completion;scanner.modalPresentationStyle=UIModalPresentationFullScreen;[owner presentViewController:scanner animated:YES completion:nil];[scanner release];};auto status=[AVCaptureDevice authorizationStatusForMediaType:AVMediaTypeVideo];if(status==AVAuthorizationStatusNotDetermined)[AVCaptureDevice requestAccessForMediaType:AVMediaTypeVideo completionHandler:^(BOOL allowed){dispatch_async(dispatch_get_main_queue(),^{if(allowed)begin();else completion({});});}];else if(status==AVAuthorizationStatusAuthorized)begin();else completion({});}
}
